using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static partial class ScreenshotFollowupRepair {
 [Serializable]public class Geometry {public string path;public Vector3[] vertices;public int[][] indices;public int[] triangles,lengths;public Vector3 min,max;public string[] materials;public int first,count;}
 [Serializable]public class GeometryStudy {public string utc;public List<Geometry> coast=new List<Geometry>(),roads=new List<Geometry>();public List<Node> texts=new List<Node>();}
 static bool Coastal(Transform t){string p=P(t),n=t.name.ToLowerInvariant();if(p.StartsWith("Root/Roads/Curbs/")){var b=t.GetComponent<Renderer>().bounds;return b.max.z<=-73.5f&&b.min.x>=-156&&b.max.x<=128||b.min.x>=108.7f&&b.max.x<=130&&b.min.z>=-94&&b.max.z<=33||b.min.z>=26.8f&&b.max.z<=31.5f&&b.min.x>=60&&b.max.x<=116;}return (Regex.IsMatch(p,@"^Root/Comps/Comp9(?:/| \((17|20|21|22|23|24)\)/)")||p.StartsWith("Root/Comps/Comp11")||p.StartsWith("Root/Comps/ParkWalkComp/"))&&Regex.IsMatch(n,@"^(sm_(wall(?!_flower)|stairs|sidewalk|street|fence|curb)|railing|sidewalk)");}
 static Geometry Geo(Transform t){var m=t.GetComponent<MeshFilter>().sharedMesh;var r=t.GetComponent<MeshRenderer>();var so=new SerializedObject(r);var b=so.FindProperty("m_StaticBatchInfo");int first=b?.FindPropertyRelative("firstSubMesh").intValue??0,count=b?.FindPropertyRelative("subMeshCount").intValue??0;var idx=Enumerable.Range(count>0?first:0,count>0?count:m.subMeshCount).Select(i=>m.GetTriangles(i)).ToArray();return new Geometry{path=P(t),vertices=m.vertices.Select(t.TransformPoint).ToArray(),triangles=idx.SelectMany(i=>i).ToArray(),lengths=idx.Select(i=>i.Length).ToArray(),indices=idx,min=r.bounds.min,max=r.bounds.max,materials=r.sharedMaterials.Select(x=>x?AssetDatabase.GetAssetPath(x):"").ToArray(),first=first,count=count};}
 public static void ExportGeometry(){var result=new GeometryStudy{utc=DateTime.UtcNow.ToString("o")};var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);Physics.SyncTransforms();foreach(var t in All(gs).Concat(All(ds))){if(P(t).StartsWith("TownRoadNetwork20261019/")&&t.GetComponent<MeshFilter>())result.roads.Add(Geo(t));if(t.GetComponent<TMPro.TMP_Text>()&&P(t).Contains("CityBuildings"))result.texts.Add(N(t));}var source=EditorSceneManager.OpenScene(Source,OpenSceneMode.Additive);Physics.SyncTransforms();foreach(var t in All(source).Where(t=>t.GetComponent<MeshFilter>()&&t.GetComponent<MeshRenderer>()&&Coastal(t)))result.coast.Add(Geo(t));File.WriteAllText(Path.Combine(Reports,"screenshot-coast-geometry.json"),JsonUtility.ToJson(result,false));EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");Debug.Log("COAST_GEOMETRY_EXPORTED "+result.coast.Count);EditorApplication.Exit(0);}
